def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_d = 0
    my_d = 0
    opp_d6 = 0
    opp_d10 = 0

    start6 = n - 6
    if start6 < 0:
        start6 = 0
    start10 = n - 10
    if start10 < 0:
        start10 = 0

    for i in range(n):
        m, o = history[i]
        if o == 'D':
            opp_d += 1
            if i >= start6:
                opp_d6 += 1
            if i >= start10:
                opp_d10 += 1
        if m == 'D':
            my_d += 1

    unprovoked = 0
    provoked = 0
    forgiven = 0
    punished = 0

    for i in range(1, n):
        pm, po = history[i - 1]
        cm, co = history[i]
        if co == 'D':
            if pm == 'C':
                unprovoked += 1
            else:
                provoked += 1
        if pm == 'D' and po == 'C':
            if co == 'C':
                forgiven += 1
            else:
                punished += 1

    opp_c_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            opp_c_streak += 1
        else:
            break

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    if n < 4:
        if last_opp == 'D':
            return 'D'
        return 'C'

    if (opp_d6 >= 5 or (n >= 12 and opp_d10 >= 6) or unprovoked >= 4 or
            (n >= 20 and opp_d > my_d + 4) or (n >= 25 and opp_d * 3 >= n * 2)):
        return 'D'

    cooperative_exploit = opp_d <= 2 and unprovoked == 0 and opp_d10 <= 1

    if n >= 96:
        if last_opp == 'D':
            return 'D'
        if cooperative_exploit and punished == 0 and forgiven >= 3:
            return 'D'
        return 'C'

    if last_opp == 'D':
        if n >= 2 and history[-2][0] == 'D':
            if opp_d_streak >= 2 or unprovoked >= 3 or (n >= 20 and opp_d > my_d + 2):
                return 'D'
            return 'C'
        if opp_d_streak >= 2 or unprovoked >= 3 or (n >= 15 and opp_d > my_d + 1):
            return 'D'
        return 'D'

    if last_me == 'D':
        if n >= 2 and history[-2][1] == 'D':
            return 'C'
        if cooperative_exploit and punished == 0 and forgiven >= 3 and my_d_streak < 10:
            return 'D'
        return 'C'

    if cooperative_exploit and punished == 0:
        if forgiven >= 3 and opp_c_streak >= 3:
            return 'D'
        if forgiven >= 1 and my_d <= 3 and n >= 18 and opp_c_streak >= 5:
            return 'D'
        if forgiven == 0 and my_d == 0 and n >= 18 and opp_c_streak >= 10 and opp_d <= 1:
            return 'D'

    return 'C'
